mapper.select:
SELECT *
FROM base_point_log l
WHERE date_format(l.time,'%Y-%m-%d') = #{format}

    and l.point_mac in

        #{item}


ORDER BY l.time DESC

SELECT
    IFNULL(count(BLD.id),0) as num
FROM ${tableLampblack} BLD
RIGHT JOIN base_point BP ON BLD.point_mac = BP.point_mac and BP.company_id = #{companyId}
WHERE BLD.yyyymmdd = #{format}

SELECT
    IFNULL(SUM(BLD.lampblack_data > 1 or BLD.matter_data >5 or BLD.nmhc_data > 10),0) as num,
    BLD.point_mac as mac
FROM ${tableLampblack} BLD
RIGHT JOIN base_point BP ON BLD.point_mac = BP.point_mac and BP.company_id = #{companyId}
WHERE BLD.yyyymmdd = #{format}

SELECT
    IFNULL(SUM(sub.num > 20),0) as a1,
    IFNULL(SUM(sub.num < 20 and sub.num > 10),0) as a2,
    IFNULL(SUM(sub.num < 10),0) as a3
FROM (
    SELECT SUM(b.alarm_type > 0) as num
    FROM base_company_type b
    WHERE   1=1

            and date_format(b.create_time,'%Y-%m') = #{format}


            and b.is_on = #{i}

            and b.fid_region= #{fidRegion}

    GROUP BY b.name
) sub

SELECT IFNULL(count(num),0) as n
FROM (
    SELECT count(b.id) as num
    FROM base_company_type b
    WHERE   1=1

            and date_format(b.create_time,'%Y-%m') = #{format}



            and b.is_on = #{i}

        and b.fid_region= #{fidRegion}
    GROUP BY b.name
) sub

UPDATE base_company_type b SET b.is_on = 1, b.updata_time = now()
WHERE 1=1
    and b.name = #{name}
    and date_format(b.create_time,'%Y-%m') = #{format}
    and b.fid_region = #{fidRegion}

UPDATE base_company_type b SET b.is_on = 1, b.updata_time = now()
WHERE 1=1
and b.id = #{companyId}

    AND date_format(BLD.create_time,'%Y-%m-%d %H:%i:%S') > #{startTime}


    AND date_format(BLD.create_time,'%Y-%m-%d %H:%i:%S') < #{endTime}
